// A maze on a grid of cells, each with its four walls. Generated by a
// depth-first walk (the "recursive backtracker"): from a cell, go to a
// random neighbor not visited yet, opening the wall between them; when
// there is none, go back. Every cell is then reachable, by a single path.

/** The walls of a cell, as bits. */
export const Wall = { North: 1, East: 2, South: 4, West: 8 } as const;

export interface Maze {
  readonly width: number;
  readonly height: number;
  // The walls of each cell (Wall bits), row by row: cell (x, z) at
  // z × width + x. North is towards -z.
  readonly cells: Uint8Array;
}

/** A reproducible random generator (mulberry32), in [0, 1). */
export function seededRandom(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// The neighbors of a cell: the offset, the wall on this side, and the wall
// on the other side.
const directions = [
  { dx: 0, dz: -1, wall: Wall.North, opposite: Wall.South },
  { dx: 1, dz: 0, wall: Wall.East, opposite: Wall.West },
  { dx: 0, dz: 1, wall: Wall.South, opposite: Wall.North },
  { dx: -1, dz: 0, wall: Wall.West, opposite: Wall.East },
];

/** A maze of `width` × `height` cells, the same for the same seed. */
export function generateMaze(width: number, height: number, seed = 1): Maze {
  const random = seededRandom(seed);
  const all = Wall.North | Wall.East | Wall.South | Wall.West;
  const cells = new Uint8Array(width * height).fill(all);
  const visited = new Uint8Array(width * height);
  // The path walked so far: going back pops it.
  const stack = [0];
  visited[0] = 1;
  while (stack.length > 0) {
    const cell = stack[stack.length - 1];
    const x = cell % width;
    const z = Math.floor(cell / width);
    const open = directions.filter(({ dx, dz }) => {
      const nx = x + dx;
      const nz = z + dz;
      return (
        nx >= 0 &&
        nx < width &&
        nz >= 0 &&
        nz < height &&
        !visited[nz * width + nx]
      );
    });
    if (open.length === 0) {
      stack.pop();
      continue;
    }
    const { dx, dz, wall, opposite } = open[Math.floor(random() * open.length)];
    const next = (z + dz) * width + x + dx;
    cells[cell] &= ~wall;
    cells[next] &= ~opposite;
    visited[next] = 1;
    stack.push(next);
  }
  return { width, height, cells };
}
